/bin/zsh -lc "python3 - <<'PY'
import json
from rest_api import RestAPI

raw = {
    \"users\": [
        {\"name\": \"Bob\", \"owes\": {}, \"owed_by\": {}, \"balance\": 0.0},
        {\"name\": \"Adam\", \"owes\": {\"Adam\": 7, \"Bob\": 0.3}, \"owed_by\": {}, \"balance\": -7},
    ]
}
api = RestAPI(json.dumps(raw))
assert json.loads(api.get(\"/users\", \"{}\"))[\"users\"][0][\"name\"] == \"Adam\"
filtered = json.loads(api.get(\"/users\", json.dumps({\"users\": [\"Adam\", \"Adam\"]})))
assert [u[\"name\"] for u in filtered[\"users\"]] == [\"Adam\"]
assert \"Adam\" not in filtered[\"users\"][0][\"owes\"]

api = RestAPI({\"users\": [
    {\"name\": \"Alice\", \"owes\": {\"Bob\": 0.3}, \"owed_by\": {}, \"balance\": -0.3},
    {\"name\": \"Bob\", \"owes\": {}, \"owed_by\": {\"Alice\": 0.3}, \"balance\": 0.3},
]})
api.post(\"/iou\", json.dumps({\"lender\": \"Alice\", \"borrower\": \"Bob\", \"amount\": 0.1}))
result = json.loads(api.post(\"/iou\", json.dumps({\"lender\": \"Alice\", \"borrower\": \"Bob\", \"amount\": 0.2})))
by_name = {u[\"name\"]: u for u in result[\"users\"]}
assert by_name[\"Alice\"][\"owes\"] == {} and by_name[\"Alice\"][\"owed_by\"] == {}
assert by_name[\"Alice\"][\"balance\"] == 0.0
assert by_name[\"Bob\"][\"owes\"] == {} and by_name[\"Bob\"][\"owed_by\"] == {}

api = RestAPI({\"users\": [{\"name\": \"Adam\", \"owes\": {}, \"owed_by\": {}, \"balance\": 0.0}]})
for amount in (0, -1):
    try:
        api.post(\"/iou\", json.dumps({\"lender\": \"Adam\", \"borrower\": \"Adam\", \"amount\": amount}))
    except ValueError:
        pass
    else:
        raise AssertionError(\"invalid IOU accepted\")
assert json.loads(api.get(\"/users\"))[\"users\"][0][\"owes\"] == {}

api = RestAPI({\"users\": [
    {\"name\": \"Adam\", \"owes\": {\"Zoe\": 1, \"Bob\": 2}, \"owed_by\": {}, \"balance\": 0},
    {\"name\": \"Bob\", \"owes\": {}, \"owed_by\": {\"Adam\": 2}, \"balance\": 0},
    {\"name\": \"Zoe\", \"owes\": {}, \"owed_by\": {\"Adam\": 1}, \"balance\": 0},
]})
adam = json.loads(api.get(\"/users\"))[\"users\"][0]
assert list(adam[\"owes\"]) == [\"Bob\", \"Zoe\"]

print(\"review edge cases: OK\")
PY"

